  "mainEntity": [
    {
      "@type": "Question",
      "name": "ما الفرق بين ورق الكوشيه والمطفي في الطباعة؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "الكوشيه سطحه لامع بفعل طبقة تلميع تزيد حدة الألوان ويناسب الكتالوجات والصور. المطفي سطحه غير عاكس يقبل الكتابة بالقلم ويريح العين في النصوص الطويلة. المفارقة أن المطفي قد يكون أعلى تكلفة رغم مظهره الأبسط بسبب المعالجة الإضافية."
      }
    },

    {
      "@type": "Question",
      "name": "ما الوزن المناسب لطباعة الكروت الشخصية؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "الوزن الأنسب يبدأ من 300 جرام فأعلى ليمنح الكارت صلابة وإحساس فخامة يجعله يُحتفظ به. الأوزان الأقل تعطي انطباعًا بمطبوع سريع الاستعمال يُرمى بعد الاستخدام الأول."
      }
    },

    {
      "@type": "Question",
      "name": "متى تكون الطباعة بالفرخ أجدى من الرزمة العادية؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "الطباعة بالفرخ (أوفست) تصبح أجدى اقتصاديًا من ألف نسخة فأكثر لأن تكلفة إعداد الزنكات وضبط الماكينة تتوزع على وحدات أكثر. تحت ألف نسخة، الطباعة الرقمية أنسب لأنها لا تحتاج إعدادًا ثابتًا."
      }
    },

    {
      "@type": "Question",
      "name": "هل يؤثر نوع الورق على درجة ظهور الألوان في المطبوع؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "نعم، تأثير جوهري. الكوشيه اللامع يعطي ألوانًا حادة ومشبعة، والمطفي يعطي ألوانًا هادئة أقل تشبعًا، والأوفست غير المطلي يمتص الحبر فتبدو الألوان أخف."
      }
    },

    {
      "@type": "Question",
      "name": "ما الأوزان المتاحة لورق الكوشيه؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "أشهر الأوزان المتاحة في السوق: 115 و170 و250 و300 جرام. الأوزان الخفيفة للنشرات الداخلية، والثقيلة لأغلفة الكتالوجات والكروت التقديمية."
      }
    },

    {
      "@type": "Question",
      "name": "لماذا تختلف نتيجة الطباعة رغم اختيار الورق الصحيح؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "السبب في الغالب ليس الورق بل الملف. ملف بنظام RGB بدل CMYK يعطي ألوانًا مختلفة، وملف بلا bleed يظهر بحواف بيضاء بعد القص، وخطوط غير مدمجة تُستبدل بخطوط أخرى وقت الطباعة."
      }
    }
  ]
